-- create-table /TRDEMOOTTO/OTTO_SHOPS
CREATE TABLE "/TRDEMOOTTO/OTTO_SHOPS" (
  "/RT/TENANT" VARCHAR(16) COLLATE "C" NOT NULL,
  "SHOP_ID" VARCHAR(12) COLLATE "C" NOT NULL,
  "COMPANY_ID" VARCHAR(10) COLLATE "C" NOT NULL,
  "NAME" VARCHAR(80) COLLATE "C" NOT NULL,
  CONSTRAINT "/TRDEMOOTTO/OTTO_SHOPS#PK" PRIMARY KEY ("/RT/TENANT", "SHOP_ID"),
  CONSTRAINT "/TRDEMOOTTO/OTTO_SHOPS#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/TRDEMOOTTO/OTTO_SHOPS#FK#CONNECTION" FOREIGN KEY ("/RT/TENANT", "COMPANY_ID") REFERENCES "/TRDEMOOTTO/OTTO_CONNECTIONS" ("/RT/TENANT", "COMPANY_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- alter-type /TRDEMOFIN/COMPANIES./TRDEMOOTTO/OTTO_ID (CHAR(20) -> CHAR(32))
ALTER TABLE "/TRDEMOFIN/COMPANIES" ALTER COLUMN "/TRDEMOOTTO/OTTO_ID" TYPE VARCHAR(32) COLLATE "C";

-- add-column /TRDEMOFIN/COMPANIES./TRDEMOOTTO/ACTIVE (BOOL)
ALTER TABLE "/TRDEMOFIN/COMPANIES" ADD COLUMN "/TRDEMOOTTO/ACTIVE" BOOLEAN NOT NULL DEFAULT FALSE;

-- add-column /TRDEMOFIN/COMPANIES./TRDEMOOTTO/MAIN_SHOP (CHAR(12))
ALTER TABLE "/TRDEMOFIN/COMPANIES" ADD COLUMN "/TRDEMOOTTO/MAIN_SHOP" VARCHAR(12) COLLATE "C";

-- alter-type /TRDEMOFIN/COMPANIES_ARCHIVE./TRDEMOOTTO/OTTO_ID (CHAR(20) -> CHAR(32)) via /TRDEMOFIN/COMPANIES
ALTER TABLE "/TRDEMOFIN/COMPANIES_ARCHIVE" ALTER COLUMN "/TRDEMOOTTO/OTTO_ID" TYPE VARCHAR(32) COLLATE "C";

-- add-column /TRDEMOFIN/COMPANIES_ARCHIVE./TRDEMOOTTO/ACTIVE (BOOL) via /TRDEMOFIN/COMPANIES
ALTER TABLE "/TRDEMOFIN/COMPANIES_ARCHIVE" ADD COLUMN "/TRDEMOOTTO/ACTIVE" BOOLEAN NOT NULL DEFAULT FALSE;

-- add-column /TRDEMOFIN/COMPANIES_ARCHIVE./TRDEMOOTTO/MAIN_SHOP (CHAR(12)) via /TRDEMOFIN/COMPANIES
ALTER TABLE "/TRDEMOFIN/COMPANIES_ARCHIVE" ADD COLUMN "/TRDEMOOTTO/MAIN_SHOP" VARCHAR(12) COLLATE "C";

-- add-foreign-key /TRDEMOFIN/COMPANIES./TRDEMOOTTO/MAIN_SHOP (references /TRDEMOOTTO/OTTO_SHOPS)
ALTER TABLE "/TRDEMOFIN/COMPANIES" ADD CONSTRAINT "/TRDEMOFIN/COMPANIES#FK#/TRDEMOOTTO/MAIN_SHOP" FOREIGN KEY ("/RT/TENANT", "/TRDEMOOTTO/MAIN_SHOP") REFERENCES "/TRDEMOOTTO/OTTO_SHOPS" ("/RT/TENANT", "SHOP_ID") DEFERRABLE INITIALLY IMMEDIATE;

